#!/usr/bin/env python3
"""Creates ~/Desktop/Conclave and opens it in Xcode. Run on your Mac."""
from pathlib import Path
import subprocess

ROOT = Path.home() / "Desktop" / "Conclave"
APP = ROOT / "Conclave"
PROJ = ROOT / "Conclave.xcodeproj"

def w(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")

def main() -> None:
    w(APP / "ConclaveApp.swift", APP_SWIFT)
    w(APP / "ContentView.swift", CONTENT_SWIFT)
    w(APP / "Info.plist", INFO)
    w(APP / "Assets.xcassets/Contents.json", '{ "info": { "author": "xcode", "version": 1 } }\n')
    w(APP / "Assets.xcassets/AccentColor.colorset/Contents.json",
      '{ "colors": [{ "idiom": "universal" }], "info": { "author": "xcode", "version": 1 } }\n')
    w(APP / "Assets.xcassets/AppIcon.appiconset/Contents.json",
      '{ "images": [{ "idiom": "universal", "platform": "ios", "size": "1024x1024" }], "info": { "author": "xcode", "version": 1 } }\n')
    w(PROJ / "project.pbxproj", PBX)
    w(PROJ / "xcshareddata/xcschemes/Conclave.xcscheme", SCHEME)
    print("Created", PROJ)
    subprocess.run(["open", str(PROJ)], check=False)

